package website

import (
	"fmt"
	"html/template"
	"log"
	"net/http"
	"strings"

	"donseba/go-webthings-docs/internal/moduledoc"

	router "github.com/donseba/go-router"
)

// guidesSite serves go-webthings' own user guides at docs.<domain>/go-webthings,
// generated by tools/moduledocs from the docs/ folder of go-webthings.
type guidesSite struct {
	docs   *docsRenderer
	guides moduledoc.Guides
	order  []*moduledoc.Guide
	groups map[string]string
}

// GuidesIndexData is the dot of the guides' overview.
type GuidesIndexData struct {
	Article DocsArticleData
	Groups  []GuideCardGroup
}

// GuideCardGroup is a group of guides on the overview.
type GuideCardGroup struct {
	Name   string
	Guides []GuideCard
}

// GuideCard links to a guide.
type GuideCard struct {
	Title   string
	Summary string
	URL     string
}

// GuidePageData is the dot of a guide.
type GuidePageData struct {
	Article  DocsArticleData
	Body     template.HTML
	Previous *ModulePageLink
	Next     *ModulePageLink
}

const (
	guidesBase = "/go-webthings"
	guidesFile = "guides/go-webthings.json"
)

func newGuidesSite() *guidesSite {
	guides, err := moduledoc.LoadGuides(websiteFS, guidesFile)
	if err != nil {
		log.Printf("guides: %v", err)
	}

	site := &guidesSite{
		guides: guides,
		groups: map[string]string{},
	}

	nav := []NavItem{{Path: "/", Label: "Overview", Group: "Start"}}

	for i := range guides.Groups {
		group := &guides.Groups[i]

		for j := range group.Guides {
			guide := &group.Guides[j]

			site.order = append(site.order, guide)
			site.groups[guide.Slug] = group.Name
			nav = append(nav, NavItem{Path: "/" + guide.Slug, Label: guide.Title, Group: group.Name})
		}
	}

	site.docs = newDocsRenderer(docsRendererConfig{
		BasePath:  guidesBase,
		AppName:   "go-webthings",
		LogoImage: "/assets/img/logo-go-webthings.png",
		Title:     "go-webthings",
		Subtitle:  "the backend of your website",
		GitHubURL: "https://github.com/donseba/go-webthings",
		Nav:       nav,
	})

	return site
}

func registerGuideRoutes(r *router.Router, domain string) {
	r.Get(guidesBase, guideDocs.overview).As(fmt.Sprintf("%s.go-webthings", domain))

	for i, guide := range guideDocs.order {
		r.Get(guidesBase+"/"+guide.Slug, func(w http.ResponseWriter, req *http.Request) {
			guideDocs.page(w, req, i)
		}).As(fmt.Sprintf("%s.go-webthings.%s", domain, guide.Slug))
	}
}

func (s *guidesSite) overview(w http.ResponseWriter, r *http.Request) {
	page := docsPage{
		Template:    "templates/guides/overview.gohtml",
		Title:       "Build a website with go-webthings",
		Description: s.guides.Summary,
		Section:     "go-webthings",
	}

	data := GuidesIndexData{Article: article(page)}

	for _, group := range s.guides.Groups {
		cards := GuideCardGroup{Name: group.Name}

		for _, guide := range group.Guides {
			cards.Guides = append(cards.Guides, GuideCard{
				Title:   guide.Title,
				Summary: guide.Summary,
				URL:     guidesBase + "/" + guide.Slug,
			})
		}

		data.Groups = append(data.Groups, cards)
	}

	s.docs.render(w, r, page, data)
}

func (s *guidesSite) page(w http.ResponseWriter, r *http.Request, index int) {
	guide := s.order[index]
	page := docsPage{
		Template:    "templates/guides/page.gohtml",
		Title:       guide.Title,
		Description: guide.Summary,
		Section:     s.groups[guide.Slug],
	}

	data := GuidePageData{
		Article: article(page),
		Body:    resolveLinks(r, guide.Body),
	}

	if index > 0 {
		previous := s.order[index-1]
		data.Previous = &ModulePageLink{Label: previous.Title, URL: guidesBase + "/" + previous.Slug}
	} else {
		data.Previous = &ModulePageLink{Label: "Overview", URL: guidesBase}
	}

	if index < len(s.order)-1 {
		next := s.order[index+1]
		data.Next = &ModulePageLink{Label: next.Title, URL: guidesBase + "/" + next.Slug}
	}

	s.docs.render(w, r, page, data)
}

// resolveLinks points the generated links to the other subdomain (see
// tools/moduledocs) at its address for this request's host.
func resolveLinks(r *http.Request, body template.HTML) template.HTML {
	html := strings.NewReplacer(
		`href="wt-docs:`, `href="`+docsHomeURL(r),
		`href="wt-modules:`, `href="`+modulesHomeURL(r),
	).Replace(string(body))

	//nolint:gosec // only link prefixes of generated, escaped HTML change.
	return template.HTML(html)
}
